283	export function mergeMissingPromptDraftAttachments(
284	  currentAttachments: readonly PromptDraftAttachment[],
285	  preservedAttachments: readonly PromptDraftAttachment[],
286	): PromptDraftAttachment[] | null {
287	  const existingPaths = new Set(
288	    currentAttachments.map((attachment) => attachment.path),
289	  );
290	  const missingAttachments = preservedAttachments.filter(
291	    (attachment) => !existingPaths.has(attachment.path),
292	  );
293	  if (missingAttachments.length === 0) {
294	    return null;
295	  }
296	  return [...currentAttachments, ...missingAttachments];
297	}
298	
299	export function restorePromptDraftAfterOptionChange({
300	  currentDraft,
301	  preservedDraft,
302	}: {
303	  currentDraft: PromptDraftState;
304	  preservedDraft: PromptDraftState | null;
305	}): PromptDraftState | null {
306	  if (preservedDraft === null) {
307	    return null;
308	  }
309	  if (arePromptDraftStatesEqual(currentDraft, preservedDraft)) {
310	    return null;
311	  }
312	
313	  let restoredDraft = currentDraft;
314	  let changed = false;
315	
316	  if (isPromptDraftEmpty(currentDraft) && !isPromptDraftEmpty(preservedDraft)) {
317	    restoredDraft = preservedDraft;
318	    changed = true;
319	  } else if (
320	    currentDraft.text === preservedDraft.text &&
321	    currentDraft.mentions !== preservedDraft.mentions &&
322	    JSON.stringify(currentDraft.mentions) !==
323	      JSON.stringify(preservedDraft.mentions)
324	  ) {
325	    restoredDraft = {
326	      ...restoredDraft,
327	      mentions: preservedDraft.mentions,
328	    };
329	    changed = true;
330	  }
331	
332	  const mergedAttachments = mergeMissingPromptDraftAttachments(
333	    restoredDraft.attachments,
334	    preservedDraft.attachments,
335	  );
336	  if (mergedAttachments !== null) {
337	    restoredDraft = {
338	      ...restoredDraft,
339	      attachments: mergedAttachments,
340	    };
341	    changed = true;
342	  }
343	
344	  return changed ? restoredDraft : null;
345	}
