544	
545	function readForkThreadCreateSeedFromLocationState(
546	  state: unknown,
547	): ForkThreadCreateSeed | null {
548	  if (!state || typeof state !== "object") return null;
549	  const candidate = (state as Record<string, unknown>)[
550	    FORK_THREAD_CREATE_SEED_LOCATION_STATE_KEY
551	  ];
552	  if (!candidate || typeof candidate !== "object") return null;
553	  const value = candidate as Record<string, unknown>;
554	  if (
555	    typeof value.environmentId !== "string" ||
556	    value.environmentId.length === 0 ||
557	    typeof value.model !== "string" ||
558	    value.model.length === 0 ||
559	    typeof value.permissionMode !== "string" ||
560	    value.permissionMode.length === 0 ||
561	    typeof value.projectId !== "string" ||
562	    value.projectId.length === 0 ||
563	    typeof value.providerId !== "string" ||
564	    value.providerId.length === 0 ||
565	    typeof value.reasoningLevel !== "string" ||
566	    value.reasoningLevel.length === 0 ||
567	    typeof value.sourceThreadId !== "string" ||
568	    value.sourceThreadId.length === 0 ||
569	    typeof value.sourceThreadTitle !== "string" ||
570	    value.sourceThreadTitle.trim().length === 0
571	  ) {
572	    return null;
573	  }
574	  // History state can outlive a release. The deprecated "workspace-write"
575	  // alias maps onto the same workspace sandbox as "accept-edits"; legacy
576	  // "readonly" (or any unknown value) invalidates the seed rather than being
577	  // silently reinterpreted as a writable mode.
578	  const seedPermissionMode =
579	    value.permissionMode === "workspace-write"
580	      ? "accept-edits"
581	      : value.permissionMode === "accept-edits" ||
582	          value.permissionMode === "auto" ||
583	          value.permissionMode === "full"
584	        ? value.permissionMode
585	        : null;
586	  if (seedPermissionMode === null) {
587	    return null;
588	  }
589	  if (
590	    value.serviceTier !== undefined &&
591	    typeof value.serviceTier !== "string"
592	  ) {
593	    return null;
594	  }
595	  if (
596	    value.sourceSeqEnd !== undefined &&
597	    (typeof value.sourceSeqEnd !== "number" ||
598	      !Number.isInteger(value.sourceSeqEnd) ||
599	      value.sourceSeqEnd < 0)
600	  ) {
601	    return null;
602	  }
603	  return {
604	    environmentId: value.environmentId,
605	    model: value.model,
606	    permissionMode: seedPermissionMode,
607	    projectId: value.projectId,
608	    providerId: value.providerId,
609	    reasoningLevel: value.reasoningLevel as ReasoningLevel,
610	    serviceTier: value.serviceTier as ServiceTier | undefined,
611	    sourceSeqEnd: value.sourceSeqEnd as number | undefined,
612	    sourceThreadId: value.sourceThreadId,
613	    sourceThreadTitle: value.sourceThreadTitle.trim(),
614	  };
615	}
